  function detectLanguage() {
    var stored = '';
    try { stored = localStorage.getItem('ledexsoft-language') || ''; } catch (e) {}
    if (['es', 'en', 'pt', 'zh'].indexOf(stored) !== -1) return stored;
    var langs = navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || ''];
    for (var i = 0; i < langs.length; i++) {
      var code = String(langs[i]).toLowerCase().split(/[-_]/)[0];
      if (['es', 'en', 'pt', 'zh'].indexOf(code) !== -1) return code;
    }
    return 'es';
  }

  function init() {
    var select = document.getElementById('siteLanguage');
    if (!select) {
      var host = document.querySelector('.nav-right, .nav-actions, .site-header, header, .project-header') || document.body;
      var label = document.createElement('label');
      label.className = 'language-switcher language-switcher--injected';
      label.setAttribute('aria-label', 'Idioma del sitio');
      label.innerHTML = '<span aria-hidden="true">◎</span><select id="siteLanguage" aria-label="Seleccionar idioma"><option value="es">ES</option><option value="en">EN</option><option value="pt">PT</option><option value="zh">中文</option></select>';
      if (host === document.body) label.classList.add('language-switcher--floating');
      host.appendChild(label);
      select = label.querySelector('select');
      var style = document.createElement('style');
      style.textContent = '.language-switcher--injected{display:inline-flex;align-items:center;gap:.35rem;padding:.38rem .55rem;border:1px solid currentColor;border-radius:999px;font:600 .75rem system-ui;opacity:.9;z-index:1000}.language-switcher--injected select{border:0;background:transparent;color:inherit;font:inherit;cursor:pointer}.language-switcher--injected option{color:#10251e;background:#fff}.language-switcher--floating{position:fixed;right:1rem;top:1rem;color:#18382f;background:#fff;box-shadow:0 2px 12px #0002}';
      document.head.appendChild(style);
    }
    var lang = detectLanguage();
    var initialTitle = document.title;
    var initialDescription = document.querySelector('meta[name="description"]');
    var initialDescriptionText = initialDescription ? initialDescription.content : '';
    var nodes = [];
    var seenNodes = new WeakSet();
    var lastDispatchedLanguage = null;
    function collectText(root) {
      var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
        acceptNode: function (node) {
        if (!node.nodeValue || !node.nodeValue.trim() || !node.parentElement) return NodeFilter.FILTER_REJECT;
        if (node.parentElement.closest('script,style,noscript,select,option,svg,.cursor,.preloader,.wipe-clock,.cumashop-iframe')) return NodeFilter.FILTER_REJECT;
        return NodeFilter.FILTER_ACCEPT;
        }
      });
      while (walker.nextNode()) {
        if (!seenNodes.has(walker.currentNode)) {
          seenNodes.add(walker.currentNode);
          nodes.push({ node: walker.currentNode, original: walker.currentNode.nodeValue });
        }
      }
    }
    collectText(document.body);
    var attributes = [];
    document.querySelectorAll('[aria-label],[title],[alt],[placeholder]').forEach(function (el) {
      ['aria-label','title','alt','placeholder'].forEach(function (attr) {
        if (el.hasAttribute(attr)) attributes.push({ element: el, name: attr, original: el.getAttribute(attr) });
      });
    });

    function apply(next) {
      var dict = translations[next] || {};
      nodes.forEach(function (entry) {
        if (!entry.node.isConnected) return;
        var original = entry.original;
        var key = original.trim();
        var translated = dict[key];
        if (translated) {
          var start = original.match(/^\s*/)[0];
          var end = original.match(/\s*$/)[0];
          entry.node.nodeValue = start + translated + end;
        } else entry.node.nodeValue = original;
      });
      attributes.forEach(function (entry) {
        if (!entry.element.isConnected) return;
        entry.element.setAttribute(entry.name, dict[entry.original] || entry.original);
      });
      document.documentElement.lang = next === 'zh' ? 'zh-Hans' : next;
      select.value = next;
      var titles = {
        es: ['LedexSoft — Software para la vida cotidiana y el comercio local', 'LedexSoft crea software para automatizar lo cotidiano y ayudar al comercio local a vender, organizarse y crecer.'],
        en: ['LedexSoft — Software for everyday life and local commerce', 'LedexSoft builds software to simplify everyday tasks and help local businesses sell, stay organized, and grow.'],
        pt: ['LedexSoft — Software para o dia a dia e o comércio local', 'A LedexSoft cria softwares para simplificar o cotidiano e ajudar o comércio local a vender, se organizar e crescer.'],
        zh: ['LedexSoft — 日常生活与本地商业软件', 'LedexSoft 开发软件，简化日常事务，帮助本地商家销售、管理并成长。']
      };
      if (initialTitle.indexOf('LedexSoft — Software para la vida cotidiana') === 0) {
        document.title = titles[next][0];
        if (initialDescription) initialDescription.content = titles[next][1];
      } else {
        document.title = dict[initialTitle] || initialTitle;
        if (initialDescription) initialDescription.content = dict[initialDescriptionText] || initialDescriptionText;
      }
      document.querySelectorAll('.nav-links a[href^="#"], .mobile-menu a[href^="#"]').forEach(function (link) {
        if (link.getAttribute('href') === '#cumashop' && next === 'en') link.setAttribute('aria-label', 'CumaShop');
      });
      lang = next;
      if (lastDispatchedLanguage !== next) {
        lastDispatchedLanguage = next;
        window.dispatchEvent(new CustomEvent('ledexsoft:languagechange', { detail: { language: next } }));
      }
    }

    select.addEventListener('change', function () {
      try { localStorage.setItem('ledexsoft-language', select.value); } catch (e) {}
      apply(select.value);
    });
    apply(lang);
    if (window.MutationObserver) {
      var observer = new MutationObserver(function (records) {
        records.forEach(function (record) {
          record.addedNodes.forEach(function (node) {
            if (node.nodeType === Node.TEXT_NODE) collectText(node.parentElement || document.body);
            else if (node.nodeType === Node.ELEMENT_NODE) {
              collectText(node);
              node.querySelectorAll('[aria-label],[title],[alt],[placeholder]').forEach(function (el) {
                ['aria-label','title','alt','placeholder'].forEach(function (attr) {
                  if (el.hasAttribute(attr) && !attributes.some(function (item) { return item.element === el && item.name === attr; })) attributes.push({ element: el, name: attr, original: el.getAttribute(attr) });
                });
              });
            }
          });
        });
        apply(lang);
      });
      observer.observe(document.body, { childList: true, subtree: true });
    }
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, { once: true });
  else init();
